+﻿using BTS9;
+using Infrastructure.Logs;
+using Microsoft.EntityFrameworkCore;
+using NPOI.HSSF.Record.Aggregates;
+using OpenAuth.App.Dto.OrderCommon;
+using OpenAuth.App.Finance.Dto;
+using OpenAuth.App.Finance.Interfaces;
+using OpenAuth.App.Interface;
+using OpenAuth.Repository.Domain;
+using OpenAuth.Repository.Domain.Sap;
+using OpenAuth.Repository.Domain.Settlement;
+using OpenAuth.Repository.Interface;
+using System;
+using System.Collections.Generic;
+using System.Linq;
+using System.Text;
+using System.Threading.Tasks;
+
+namespace OpenAuth.App.Finance
+{
+    /// <summary>
+    /// 退货未关联新单据处理器
+    /// </summary>
+    public class ReturnUnRelNewOrderProcessor : OnlyUnitWorkBaeApp, IPenaltyRuleProcessor
+    {
+        /// <summary>
+        /// 构造函数
+        /// </summary>
+        public ReturnUnRelNewOrderProcessor(IUnitWork unitWork, IAuth auth) : base(unitWork, auth)
+        {
+        }
+
+        /// <summary>
+        /// 处理器代码
+        /// </summary>
+        public string HandlerCode => "HANDLER_RETURN_UNRELNEWORDER";
+
+        ///<summary>
+        /// 处理器方法
+        /// </summary>
+        public async Task<(List<PenaltyEventData> NewEvents, List<ResolvedEventData> ResolvedEvents, List<CanceledEventData> CanceledEvents)> ProcessAsync(IEnumerable<PenaltyRuleDefinition> matchedRules)
+        {
+            var newEvents = new List<PenaltyEventData>();
+            // 这种简单处理器通常只对应一个规则
+            var rule = matchedRules.FirstOrDefault();
+            if (rule == null)
+            {
+                return (newEvents, new List<ResolvedEventData>(), new List<CanceledEventData>());
+            }
+
+
+            try
+            {         
+                var allOslps = await UnitWork.Find<OSLP>(null)
+                                       .ToListAsync();
+                var slpCodeToNameMap = allOslps
+                    .ToDictionary(
+                        x => x.SlpCode,
+                        x => x.SlpName
+                    );
+                // 排除售后
+                //var csOrders = UnitWork.Find<sale_ordr>(x => x.U_ERPFrom == "4" && x.sbo_id == Define.SBO_ID).Select(x => x.DocEntry.Value).ToHashSet();
+                //首先要找到已结算的单据，已结算的单据退货，才需要重新关联新单据
+                //U_DevEntry 为关联的要退的订单号，U_New_OrdrID为关联的新订单号,
+                //若 U_New_OrdrID 没有值，且价格>0的物料全部退完，则说明这个单里的有价物料全退掉了，要计算罚息
+                //罚息基础金额 = 订单中价格=0的物料的 sum(DelivrdQty * LastPurPrc)
+                //若 U_New_OrdrID 有值，则说明这个单是空退, 无实际退货，只是将单据物料关联在新的 U_New_OrdrID 订单上 不用罚息
+                var returnItems = await (from r1 in UnitWork.Find<RIN1>(null)
+                                            join r in UnitWork.Find<ORIN>(null) on r1.DocEntry equals r.DocEntry
+                                            join m in UnitWork.Find<OITM>(null) on r1.ItemCode equals m.ItemCode
+                                            where r.CANCELED == "N" && (r.U_New_ORDRID == null || r.U_New_ORDRID == "")
+                                            select new { r.DocEntry, r.U_New_ORDRID, r1.ItemCode, r1.Price, r.U_DevEntry, r1.Quantity, r1.StockValue, m.LastPurPrc, r.CreateDate, r1.BaseEntry, r1.BaseType }).ToListAsync();
+
+                // U_DevEntry 为空时，通过 RIN1 → INV1 → DLN1 回溯原始订单号
+                var nullDevEntryItems = returnItems.Where(x => string.IsNullOrEmpty(x.U_DevEntry) && x.DocEntry.HasValue && x.BaseEntry.HasValue).ToList();
+                var resolvedDevEntryMap = new Dictionary<int, int>(); // ORIN.DocEntry → 原始ORDR.DocEntry
+                if (nullDevEntryItems.Any())
+                {
+                    // 提取回溯所需数据：(ORIN.DocEntry, RIN1.BaseEntry, RIN1.BaseType)
+                    var traceItems = nullDevEntryItems
+                        .Select(x => (OrinDocEntry: x.DocEntry.Value, BaseEntry: x.BaseEntry.Value, BaseType: x.BaseType ?? 0))
+                        .Distinct()
+                        .ToList();
+                    resolvedDevEntryMap = await ResolveOrderDocEntryFromReturnChainAsync(traceItems);
+                }
+
+                // 合并：有 U_DevEntry 的直接用，没有的用回溯结果
+                var returnItemsWithDevEntry = returnItems.Select(x => new
+                {
+                    x.DocEntry, x.U_New_ORDRID, x.ItemCode, x.Price, x.Quantity, x.StockValue, x.LastPurPrc, x.CreateDate,
+                    ResolvedDevEntry = !string.IsNullOrEmpty(x.U_DevEntry)
+                        ? (int.TryParse(x.U_DevEntry, out var parsed) ? parsed : 0)
+                        : (x.DocEntry.HasValue && resolvedDevEntryMap.TryGetValue(x.DocEntry.Value, out var resolved) ? resolved : 0)
+                }).Where(x => x.ResolvedDevEntry > 0 
+                //&& !csOrders.Contains(x.ResolvedDevEntry)
+                ).ToList();
+
+                var returnProducts = returnItemsWithDevEntry.Where(m => m.Price > 0).ToList();
+                var hadPenaltyOrdrs = (await (from pd in UnitWork.Find<PenaltyRuleDefinition>(null)
+                                              join r in UnitWork.Find<PenaltyEvent>(null) on pd.Id equals r.RuleDefinitionId
+                                              where pd.RuleHandlerCode == HandlerCode
+                                              select Convert.ToInt32(r.TriggerDocEntry)).ToListAsync()).ToHashSet();
+
+                var returnProductsInFilter = returnProducts
+                    .Where(x => !hadPenaltyOrdrs.Contains(x.ResolvedDevEntry))
+                    .Select(x => new { x.DocEntry, x.CreateDate, x.Quantity, x.ItemCode, x.Price, U_DevEntry = x.ResolvedDevEntry })
+                    .ToList();
+                var returnOrdrDocEntrys = returnProductsInFilter.Select(x => x.U_DevEntry).Distinct().ToList();
+
+                var delivrdItems = await (from r1 in UnitWork.Find<RDR1>(null)
+                                             join r in UnitWork.Find<ORDR>(null) on r1.DocEntry equals r.DocEntry
+                                             join m in UnitWork.Find<OITM>(null) on r1.ItemCode equals m.ItemCode
+                                             where
+                                                r.CANCELED == "N" && r.DocStatus == "C" && r1.DelivrdQty > 0 && r1.LineStatus == "C" && r1.OpenQty == 0 && m.InvntItem == "Y"
+                                                &&  returnOrdrDocEntrys.Contains(r.DocEntry)
+                                             select new { r.DocEntry, r1.LineNum, r1.ItemCode, r1.DelivrdQty, r1.Price,m.ManSerNum, m.ManBtchNum ,m.LastPurPrc,r.SlpCode}
+                ).ToListAsync();
+                //delivrdItems = delivrdItems.Where( r=> !csOrders.Contains(r.DocEntry)).ToList();
+                var delivrdProducts = delivrdItems.Where(x => x.Price > 0).ToList();
+
+                var delivrdProductsLookUp = delivrdProducts.ToLookup(x => x.DocEntry);
+                foreach (var group in returnProductsInFilter.GroupBy(x => x.U_DevEntry))
+                {
+                    var penaltyEvent = TryCreatePenaltyEventForOrder(
+                        group,
+                        delivrdProductsLookUp,
+                        returnItemsWithDevEntry,
+                        delivrdItems,
+                        rule.Id,
+                        slpCodeToNameMap);
+
+                    if(penaltyEvent != null)
+                    {
+                        newEvents.Add(penaltyEvent);
+                    }
+                }
+            }
+            catch (Exception ex)
+            {
+                LogHelper.Error(ex, "处理退货未关联新单据处理器失败",nameof(ReturnUnRelNewOrderProcessor),nameof(ProcessAsync));
+            }
+            return (newEvents, new List<ResolvedEventData>(), new List<CanceledEventData>());
+        }
+
+        /// <summary>
+        /// 尝试为订单创建罚息事件
+        /// </summary>
+        private PenaltyEventData TryCreatePenaltyEventForOrder(
+            IGrouping<int, dynamic> group,
+            ILookup<int, dynamic> delivrdProductsLookUp,
+            List<dynamic> returnItemsWithDevEntry,
+            List<dynamic> delivrdItems,
+            string ruleId,
+            Dictionary<string, string> slpCodeToNameMap)
+        {
+            var thisOrdrReturnItems = group.GroupBy(x => x.ItemCode)
+                .Select(x => new { ItemCode = x.Key, TotalQty = x.Sum(s => s.Quantity) })
+                .ToDictionary(k => k.ItemCode, v => v.TotalQty);
+
+            var delivrdItemsInThisOrdr = delivrdProductsLookUp[group.Key]
+                .GroupBy(x => x.ItemCode)
+                .Select(x => new { ItemCode = x.Key, TotalQty = x.Sum(s => s.DelivrdQty) })
+                .ToDictionary(k => k.ItemCode, v => v.TotalQty);
+
+            // 遍历订单中所有有价物料，检查每个物料是否都已退完
+            if (!AreAllPriceableItemsReturned(delivrdItemsInThisOrdr, thisOrdrReturnItems))
+            {
+                return null;
+            }
+
+            var returnedZeroPriceQtyByItem = GetReturnedZeroPriceQuantityByItem(returnItemsWithDevEntry, group.Key);
+            var fixedPenaltyAmount = CalculateFixedPenaltyAmount(delivrdItems, group.Key, returnedZeroPriceQtyByItem);
+            var slpCode = GetSalesPersonCode(delivrdItems, group.Key);
+
+            if (!fixedPenaltyAmount.HasValue || fixedPenaltyAmount == 0)
+            {
+                return null;
+            }
+
+            var latestDate = group.OrderByDescending(x => x.CreateDate).First().CreateDate;
+
+            return new PenaltyEventData
+            {
+                RuleDefinitionId = ruleId,
+                SlpCode = slpCode,
+                SlpName = slpCodeToNameMap[slpCode.Value],
+                TriggerDocType = "ORDR",
+                TriggerDocEntry = group.Key.ToString(),
+                SEDocEntry = group.Key,
+                PenaltyBaseAmount = fixedPenaltyAmount.Value,
+                TriggerEventDate = latestDate,
+                PenaltyStartDate = latestDate,
+            };
+        }
+
+        /// <summary>
+        /// 检查所有有价物料是否都已退货
+        /// </summary>
+        private bool AreAllPriceableItemsReturned(Dictionary<string, decimal> delivrdItems, Dictionary<string, decimal> returnedItems)
+        {
+            return delivrdItems.All(x =>
+                x.Value == (returnedItems.TryGetValue(x.Key, out var returnedQty) ? returnedQty : 0));
+        }
+
+        /// <summary>
+        /// 获取零价格物料的已退数量
+        /// </summary>
+        private Dictionary<string, decimal> GetReturnedZeroPriceQuantityByItem(List<dynamic> returnItemsWithDevEntry, int orderDocEntry)
+        {
+            return returnItemsWithDevEntry
+                .Where(x => x.Price == 0 && x.ResolvedDevEntry == orderDocEntry)
+                .GroupBy(x => x.ItemCode)
+                .ToDictionary(g => g.Key, g => g.Sum(s => s.Quantity));
+        }
+
+        /// <summary>
+        /// 计算固定罚息金额
+        /// </summary>
+        private decimal? CalculateFixedPenaltyAmount(List<dynamic> delivrdItems, int orderDocEntry, Dictionary<string, decimal> returnedZeroPriceQtyByItem)
+        {
+            return delivrdItems
+                .Where(x => x.Price == 0 && x.DocEntry == orderDocEntry)
+                .GroupBy(x => x.ItemCode)
+                .Sum(g =>
+                {
+                    var totalDelivrdQty = g.Sum(s => s.DelivrdQty);
+                    returnedZeroPriceQtyByItem.TryGetValue(g.Key, out var returnedQty);
+                    var unreturnedQty = totalDelivrdQty - (returnedQty ?? 0);
+                    return unreturnedQty > 0 ? unreturnedQty * g.First().LastPurPrc : (decimal?)0;
+                });
+        }
+
+        /// <summary>
+        /// 获取销售员代码
+        /// </summary>
+        private int? GetSalesPersonCode(List<dynamic> delivrdItems, int orderDocEntry)
+        {
+            return delivrdItems.FirstOrDefault(x => x.Price == 0 && x.DocEntry == orderDocEntry)?.SlpCode;
+        }
+
+        /// <summary>
+        /// U_DevEntry 为空时，通过 RIN1 → INV1 → DLN1 链路回溯原始订单号
+        /// </summary>
+        private async Task<Dictionary<int, int>> ResolveOrderDocEntryFromReturnChainAsync(
+            List<(int OrinDocEntry, int BaseEntry, int BaseType)> traceItems)
+        {
+            var result = new Dictionary<int, int>();
+
+            // 按 BaseType 分组
+            var invoiceBaseEntries = traceItems
+                .Where(x => x.BaseType == 13)
+                .Select(x => new { x.OrinDocEntry, InvDocEntry = x.BaseEntry })
+                .Distinct()
+                .ToList();
+
+            var deliveryBaseEntries = traceItems
+                .Where(x => x.BaseType == 15)
+                .Select(x => new { x.OrinDocEntry, DlnDocEntry = x.BaseEntry })
+                .Distinct()
+                .ToList();
+
+            // 路径一：RIN1.BaseType=13(发票) → INV1.BaseEntry → DLN1.BaseEntry → ORDR
+            if (invoiceBaseEntries.Any())
+            {
+                var invDocEntries = invoiceBaseEntries.Select(x => x.InvDocEntry).Distinct().ToList();
+
+                // INV1 → DLN1
+                var inv1ToDln1 = await UnitWork.Find<INV1>(x =>
+                    invDocEntries.Contains(x.DocEntry.Value) && x.BaseType == 15 && x.BaseEntry.HasValue)
+                    .Select(x => new { x.DocEntry, x.BaseEntry })
+                    .Distinct()
+                    .ToListAsync();
+                var dlnDocEntries = inv1ToDln1.Select(x => x.BaseEntry.Value).Distinct().ToList();
+
+                // DLN1 → ORDR
+                var dln1ToOrdr = await UnitWork.Find<DLN1>(x =>
+                    dlnDocEntries.Contains(x.DocEntry.Value) && x.BaseType == 17 && x.BaseEntry.HasValue)
+                    .Select(x => new { x.DocEntry, x.BaseEntry })
+                    .Distinct()
+                    .ToListAsync();
+                var dln1ToOrdrDict = dln1ToOrdr.ToDictionary(x => x.DocEntry.Value, x => x.BaseEntry.Value);
+
+                // 组装：INV1.DocEntry → DLN1.DocEntry → ORDR.DocEntry
+                var invToOrdrDict = inv1ToDln1
+                    .Where(x => dln1ToOrdrDict.ContainsKey(x.BaseEntry.Value))
+                    .GroupBy(x => x.DocEntry.Value)
+                    .ToDictionary(g => g.Key, g => dln1ToOrdrDict[g.First().BaseEntry.Value]);
+
+                foreach (var item in invoiceBaseEntries)
+                {
+                    if (invToOrdrDict.TryGetValue(item.InvDocEntry, out var ordrDocEntry))
+                        result.TryAdd(item.OrinDocEntry, ordrDocEntry);
+                }
+            }
+
+            // 路径二：RIN1.BaseType=15(交货单) → DLN1.BaseEntry → ORDR
+            if (deliveryBaseEntries.Any())
+            {
+                var dlnDocEntries = deliveryBaseEntries.Select(x => x.DlnDocEntry).Distinct().ToList();
+
+                var dln1ToOrdr = await UnitWork.Find<DLN1>(x =>
+                    dlnDocEntries.Contains(x.DocEntry.Value) && x.BaseType == 17 && x.BaseEntry.HasValue)
+                    .Select(x => new { x.DocEntry, x.BaseEntry })
+                    .Distinct()
+                    .ToListAsync();
+                var dln1ToOrdrDict = dln1ToOrdr.ToDictionary(x => x.DocEntry.Value, x => x.BaseEntry.Value);
+
+                foreach (var item in deliveryBaseEntries)
+                {
+                    if (dln1ToOrdrDict.TryGetValue(item.DlnDocEntry, out var ordrDocEntry))
+                        result.TryAdd(item.OrinDocEntry, ordrDocEntry);
+                }
+            }
+
+            return result;
+        }
+    }
+}
